DROP POLICY IF EXISTS "Owner can view session" ON public.builder_sessions;
CREATE POLICY "Owner can view session" ON public.builder_sessions FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR app_private.has_role(auth.uid(), 'admin'::app_role)));
DROP POLICY IF EXISTS "Admin can manage all sessions" ON public.builder_sessions;
CREATE POLICY "Admin can manage all sessions" ON public.builder_sessions FOR ALL TO authenticated USING (app_private.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "Admin can view otp" ON public.otp_codes;
CREATE POLICY "Admin can view otp" ON public.otp_codes FOR SELECT TO authenticated USING (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "Admins view all leads" ON public.contact_submissions;
CREATE POLICY "Admins view all leads" ON public.contact_submissions FOR SELECT TO authenticated USING (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "Admins manage leads" ON public.contact_submissions;
CREATE POLICY "Admins manage leads" ON public.contact_submissions FOR ALL TO authenticated USING (app_private.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "plans public read active" ON public.plans;
CREATE POLICY "plans public read active" ON public.plans FOR SELECT USING (((is_active = true) OR app_private.has_role(auth.uid(), 'admin'::app_role)));
DROP POLICY IF EXISTS "plans admin write" ON public.plans;
CREATE POLICY "plans admin write" ON public.plans FOR ALL USING (app_private.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "gateways public read enabled" ON public.payment_gateways;
CREATE POLICY "gateways public read enabled" ON public.payment_gateways FOR SELECT USING (((is_enabled = true) OR app_private.has_role(auth.uid(), 'admin'::app_role)));
DROP POLICY IF EXISTS "gateways admin write" ON public.payment_gateways;
CREATE POLICY "gateways admin write" ON public.payment_gateways FOR ALL USING (app_private.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "payments own read" ON public.payment_submissions;
CREATE POLICY "payments own read" ON public.payment_submissions FOR SELECT USING (((auth.uid() = user_id) OR app_private.has_role(auth.uid(), 'admin'::app_role)));
DROP POLICY IF EXISTS "payments admin update" ON public.payment_submissions;
CREATE POLICY "payments admin update" ON public.payment_submissions FOR UPDATE USING (app_private.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "payments admin delete" ON public.payment_submissions;
CREATE POLICY "payments admin delete" ON public.payment_submissions FOR DELETE USING (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "products public read active" ON public.products;
CREATE POLICY "products public read active" ON public.products FOR SELECT USING (((is_active = true) OR app_private.has_role(auth.uid(), 'admin'::app_role) OR (EXISTS ( SELECT 1 FROM sites s WHERE ((s.id = products.site_id) AND (s.user_id = auth.uid()))))));
DROP POLICY IF EXISTS "products owner write" ON public.products;
CREATE POLICY "products owner write" ON public.products FOR ALL USING (((EXISTS ( SELECT 1 FROM sites s WHERE ((s.id = products.site_id) AND (s.user_id = auth.uid())))) OR app_private.has_role(auth.uid(), 'admin'::app_role))) WITH CHECK (((EXISTS ( SELECT 1 FROM sites s WHERE ((s.id = products.site_id) AND (s.user_id = auth.uid())))) OR app_private.has_role(auth.uid(), 'admin'::app_role)));
DROP POLICY IF EXISTS "orders owner or buyer read" ON public.orders;
CREATE POLICY "orders owner or buyer read" ON public.orders FOR SELECT USING ((app_private.has_role(auth.uid(), 'admin'::app_role) OR (auth.uid() = buyer_user_id) OR (EXISTS ( SELECT 1 FROM sites s WHERE ((s.id = orders.site_id) AND (s.user_id = auth.uid()))))));
DROP POLICY IF EXISTS "orders owner update" ON public.orders;
CREATE POLICY "orders owner update" ON public.orders FOR UPDATE USING ((app_private.has_role(auth.uid(), 'admin'::app_role) OR (EXISTS ( SELECT 1 FROM sites s WHERE ((s.id = orders.site_id) AND (s.user_id = auth.uid())))))) WITH CHECK ((app_private.has_role(auth.uid(), 'admin'::app_role) OR (EXISTS ( SELECT 1 FROM sites s WHERE ((s.id = orders.site_id) AND (s.user_id = auth.uid()))))));
DROP POLICY IF EXISTS "Anyone can view active reviews" ON public.reviews;
CREATE POLICY "Anyone can view active reviews" ON public.reviews FOR SELECT TO anon, authenticated USING (((is_active = true) OR app_private.has_role(auth.uid(), 'admin'::app_role)));
DROP POLICY IF EXISTS "Admins can manage reviews" ON public.reviews;
CREATE POLICY "Admins can manage reviews" ON public.reviews FOR ALL TO authenticated USING (app_private.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (app_private.has_role(auth.uid(), 'admin'::app_role));
DROP POLICY IF EXISTS "Anyone can view enabled payment gateways" ON public.payment_gateways;
CREATE POLICY "Anyone can view enabled payment gateways" ON public.payment_gateways FOR SELECT TO anon, authenticated USING (((is_enabled = true) OR app_private.has_role(auth.uid(), 'admin'::app_role)));
REVOKE EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) FROM anon;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) FROM authenticated;
REVOKE EXECUTE ON FUNCTION app_private.has_role(uuid, public.app_role) FROM anon;